import sys
src = open('/app/index.html').read()
pre = """<script>
(() => {
  const q = new URLSearchParams(location.search);
  const ff = +(q.get('ff') || 1), until = +(q.get('until') || 1e9);
  let fake = 0, frames = 0, simT = 0;
  const raf = window.requestAnimationFrame.bind(window);
  let pending = null;
  window.requestAnimationFrame = cb => { pending = cb; return 1; };
  window.cancelAnimationFrame = () => { pending = null; };
  const t0 = performance.now();
  function pump() {
    for (let i = 0; i < ff && pending; i++) {
      if (simT >= until) break;
      const cb = pending; pending = null; fake += 50; simT += 0.05; frames++;
      script(simT);
      cb(fake + 100000);
    }
    window.__stats = { frames, simT, real: performance.now() - t0 };
    raf(pump);
  }
  raf(pump);
  // scripted pointer
  const mode = q.get('ptr') || '';
  function ev(type, x, y) { window.dispatchEvent(new PointerEvent(type, { clientX: x, clientY: y, pointerType: 'mouse', bubbles: true })); }
  function script(t) {
    const W = innerWidth, H = innerHeight;
    if (mode === 'hold') ev('pointermove', W * +(q.get('px') || 0.5), H * +(q.get('py') || 0.5));
    if (mode === 'sweep') { const u = (t % 2) / 2; ev('pointermove', W * (0.3 + 0.4 * u), H * +(q.get('py') || 0.3) + Math.sin(t * 5) * 20); }
    if (mode === 'stir') { const a = t * 3.2; ev('pointermove', W * 0.5 + Math.cos(a) * H * 0.09, H * 0.6 + Math.sin(a) * H * 0.04); }
    if (mode === 'click' && Math.abs(t - +(q.get('ct') || 1)) < 0.026) { ev('pointermove', W * +(q.get('px') || 0.5), H * +(q.get('py') || 0.6)); ev('pointerdown', W * +(q.get('px') || 0.5), H * +(q.get('py') || 0.6)); }
  }
  window.addEventListener('error', e => console.log('ERR', e.message, e.lineno, e.colno));
  setTimeout(() => console.log('STATS', JSON.stringify(window.__stats)), +(q.get('log') || 2500));
})();
</script>"""
src = src.replace('<canvas id="scene"', pre + '<canvas id="scene"', 1)
open('<TMP>/shots/test.html', 'w').write(src)
EOF
